// frontend/src/requests/requests.js

export async function sendRequest({ operation, imageFile, secondImageFile = null, params = {} }) {
  // Yeni bir FormData nesnesi oluşturuyoruz
  const formData = new FormData();
  formData.append("file", imageFile);  // Birinci görseli ekliyoruz

  // Eğer ikinci bir görsel varsa, onu da ekliyoruz
  if (secondImageFile) {
    formData.append("file2", secondImageFile);
  }

  // Parametreleri formData'ya ekliyoruz
  for (const key in params) {
    if (params[key] !== null && params[key] !== undefined) {
      formData.append(key, params[key]);
    }
  }

  try {
    // Backend'e POST isteği gönderiyoruz
    const response = await fetch(`http://127.0.0.1:8000/process/${operation}`, {
      method: "POST",
      body: formData, // FormData'yı gönderiyoruz
    });

    // Eğer yanıt başarılı değilse hata fırlatıyoruz
    if (!response.ok) {
      throw new Error("Sunucudan geçerli yanıt alınamadı");
    }

    // Başarılı yanıt geldiyse JSON formatında sonucu döndürüyoruz
    return await response.json();
  } catch (error) {
    // Hata durumunda hata mesajını logluyoruz ve null döndürüyoruz
    console.error("İstek başarısız:", error);
    return null;
  }
}
